#!/usr/bin/env node
/**
 * fix-authorized-wording.js
 *
 * PRD 15.2: replace the word "authorized" with "core" across the site
 * (e.g. "Authorized Distributor" -> "Core Distributor").
 *
 * Scope: data/**\/*.json, templates/**\/*.html, and top-level static pages.
 * Does NOT touch output/ (build artifact — regenerated by the build).
 *
 * Usage: node scripts/fix-authorized-wording.js [--apply]   (default: dry run)
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const APPLY = process.argv.includes('--apply');

function swap(text) {
  return text
    .replace(/\bAuthorized\b/g, 'Core')
    .replace(/\bauthorized\b/g, 'core')
    .replace(/\bAUTHORIZED\b/g, 'CORE');
}

function walk(dir, exts, out) {
  let items; try { items = fs.readdirSync(dir); } catch (e) { return; }
  for (const it of items) {
    if (it === 'output' && path.resolve(dir) === path.resolve(ROOT)) continue;
    if (it === 'node_modules' || it === '.git') continue;
    const full = path.join(dir, it);
    let st; try { st = fs.statSync(full); } catch (e) { continue; }
    if (st.isDirectory()) { walk(full, exts, out); continue; }
    if (exts.some(e => it.endsWith(e))) out.push(full);
  }
}

const files = [];
walk(path.join(ROOT, 'data'), ['.json'], files);
walk(path.join(ROOT, 'templates'), ['.html'], files);
for (const f of ['index.html', '404.html']) if (fs.existsSync(path.join(ROOT, f))) files.push(path.join(ROOT, f));
for (const d of ['about', 'news']) walk(path.join(ROOT, d), ['.html'], files);

let changed = 0, replacements = 0;
for (const f of files) {
  let t; try { t = fs.readFileSync(f, 'utf8'); } catch (e) { continue; }
  const n = swap(t);
  if (n !== t) {
    const count = (t.match(/\bauthorized\b|\bAuthorized\b|\bAUTHORIZED\b/g) || []).length;
    replacements += count;
    changed++;
    if (APPLY) fs.writeFileSync(f, n, 'utf8');
  }
}
console.log(`${APPLY ? 'Applied' : 'Would change'}: ${changed} files, ${replacements} occurrences`);
if (!APPLY) console.log('(dry run — re-run with --apply)');
